import ghidra.app.script.GhidraScript;import ghidra.app.emulator.EmulatorHelper;import java.io.*;
public class ZRound38FragmentTerrainOracle extends GhidraScript{
 static final long RET=0x12345000L,S=0x7fff0000L;int random,draws;
 long read(EmulatorHelper e,long a,int n){byte[]b=e.readMemory(toAddr(a),n);long v=0;for(int i=0;i<n;i++)v|=(b[i]&255L)<<(i*8);return v;}
 void put(EmulatorHelper e,long a,int n,long v)throws Exception{e.writeMemoryValue(toAddr(a),n,v);}
 long hash(byte[]b){long h=2166136261L;for(byte x:b)h=((h^(x&255))*16777619L)&0xffffffffL;return h;}
 void call(EmulatorHelper e,long entry,int ecx,int edx,int s)throws Exception{e.writeRegister("ESP",S);put(e,S,4,RET);e.writeRegister("ECX",ecx);e.writeRegister("EDX",edx);if(!e.run(toAddr(entry),null,monitor))throw new Exception(e.getLastError());while(e.readRegister("EIP").longValue()!=RET){long pc=e.readRegister("EIP").longValue(),sp=e.readRegister("ESP").longValue();if(pc==0x460910){e.writeRegister("EAX",(s*2027)^(random*7919)^0x7731a5c9);random++;}else if(pc==0x42f430)draws++;else throw new Exception("bad"+Long.toHexString(pc));long ret=read(e,sp,4);e.writeRegister("ESP",sp+4);if(!e.run(toAddr(ret),null,monitor))throw new Exception(e.getLastError());}}
 void set(EmulatorHelper e,int c,int index)throws Exception{put(e,0x586aaaL+c,1,index>=240?index-240:index);put(e,0x58aaaaL+c,1,index>=240?128:0);}
 public void run()throws Exception{try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){for(int s=0;s<1024;s++){EmulatorHelper e=new EmulatorHelper(currentProgram);try{random=draws=0;for(long p:new long[]{RET,0x460910,0x42f430})e.setBreakpoint(toAddr(p));int world=new int[]{0,3,1,4,2}[s%5];put(e,0x622dc4,1,0);put(e,0x622c7a,2,0);put(e,0x625eae,1,world);call(e,0x42e1a0,0,0,s);call(e,0x41f7e0,0,0,s);long tables=hash(e.readMemory(toAddr(0x5b65e2),592));e.writeMemory(toAddr(0x586aaa),new byte[16384]);e.writeMemory(toAddr(0x58aaaa),new byte[16384]);int c=8256;int[]first={-1,-1,-1};for(int i=0;i<480;i++){int cl=(byte)read(e,0x5b65e2L+i,1);if(cl>=0&&cl<3&&first[cl]<0)first[cl]=i;}
 int category=s/5%4;int oldclass=new int[]{-1,0,1,2}[s/20%4];int index=category<3?first[category]:-1;if(index>=0)set(e,c,index);else{int word=(int)read(e,0x5b67e2+(s%12)*2,2);put(e,0x586aaa+c,1,word);put(e,0x58aaaa+c,1,word>>8);}
 int mask=s/80%16;int[][]squares={{1,-127,-128},{128,129,1},{128,127,-1},{-1,-128,-129}};for(int k=0;k<4;k++)if((mask&(1<<k))!=0)for(int d:squares[k]){int word=(int)read(e,0x5b67e2+(s%12)*2,2);put(e,0x586aaa+c+d,1,word);put(e,0x58aaaa+c+d,1,word>>8);}
 put(e,0x4a6f4b,1,oldclass);int mode=s/512;call(e,mode==0?0x41fda0:0x420e20,0,c,s);out.println("{\"scenario\":"+s+",\"tables\":"+tables+",\"random\":"+random+",\"draws\":"+draws+",\"class\":"+(byte)read(e,0x4a6f4b,1)+",\"tiles\":"+hash(e.readMemory(toAddr(0x586aaa),16384))+",\"terrain\":"+hash(e.readMemory(toAddr(0x58aaaa),16384))+"}");}finally{e.dispose();}}}}
}